// tb_gate_sdf.sv — F4 delay-annotated gate-level simulation (SDF back-annotation).
//
// Instantiates the synthesized netlist (mcu_top) with the upstream Nangate45
// Verilog models (synth/nangate45_upstream.v, which carry `specify` blocks)
// and back-annotates real liberty-derived delays via $sdf_annotate from
// synth/mcu.sdf (generated by synth/gen_sdf.py).
//
// Behavioral SRAM/ROM models (rtl/bootrom.sv, rtl/sram.sv) are substituted
// for the blackbox stubs — same declared abstraction as F2/F3, zero-delay.
//
// Bring-up strategy: START SMALL.
//   1. fw/build/hello.hex (+expect="TEST hello PASS"): validates SDF
//      annotation and basic functionality.
//   2. fw/build/pingpong.hex (+expect="MARK pong"): FreeRTOS scheduler.
// UART output must match the zero-delay runs exactly.
//
// Clock: +clk_period_ns=<ns> (default 20 = 50 MHz). The UART receiver is
// parameterized by the actual clock period (115200 baud => 8680 ns/bit).
// Timing violations: the upstream models' $setuphold checks print warnings;
// any NOTIFIER firing or UART mismatch vs zero-delay = timing failure.
//
// Usage (from repo root):
//   iverilog -g2012 -o build/gate_sdf/tb_gate_sdf.vvp \
//     synth/nangate45_upstream.v synth/mcu_netlist.v \
//     rtl/bootrom.sv rtl/sram.sv tb/tb_gate_sdf.sv
//   vvp build/gate_sdf/tb_gate_sdf.vvp +hex=fw/build/hello.hex \
//     +expect="TEST hello PASS" +clk_period_ns=20 +timeout_cycles=1000000

`timescale 1ns/1ps

module tb_gate_sdf;

  // ---------------- clock (plusarg-controlled for timing closure) ----------------
  real clk_period_ns = 20.0;
  logic clk = 1'b0;
  initial begin
    if ($value$plusargs("clk_period_ns=%f", clk_period_ns))
      $display("TB_SDF: clock period = %0.2f ns (%0.2f MHz)",
               clk_period_ns, 1000.0/clk_period_ns);
    else
      $display("TB_SDF: clock period = 20.00 ns (50.00 MHz, default)");
    forever #(clk_period_ns/2.0) clk = ~clk;
  end

  logic rst = 1'b1;
  logic [63:0] cycle = 64'd0;
  always @(posedge clk) begin
    if (rst) cycle <= 64'd0;
    else     cycle <= cycle + 64'd1;
  end

  // ---------------- DUT (gate netlist) ----------------
  mcu_top dut (
    .clk(clk), .rst(rst),
    .uart_tx(), .uart_rx(1'b1),
    .spi_sck(), .spi_mosi(), .spi_miso(1'b1), .spi_cs_n(),
    .gpio_in(8'h00), .gpio_out(), .gpio_oe(),
    .tb_test_irq(1'b0),
    .dbg_pc(), .dbg_instr_valid(), .dbg_trap_taken(), .dbg_mcause()
  );

  // ---------------- SDF back-annotation ----------------
  // INSTANCE paths in synth/mcu.sdf are relative to `dut` (see gen_sdf.py
  // --dut). A silent non-annotation is a FAILURE: Icarus prints warnings
  // for unannotated cells/instances; the runner script greps for them.
  string sdf_path;
  initial begin
    if (!$value$plusargs("sdf=%s", sdf_path))
      sdf_path = "synth/mcu.sdf";
    $display("TB_SDF: annotating %s onto dut", sdf_path);
    $sdf_annotate(sdf_path, dut);
    $display("TB_SDF: $sdf_annotate call done");
  end

  // ---------------- firmware ----------------
  string hex_path, expect_str;
  initial begin
    if (!$value$plusargs("hex=%s", hex_path)) begin
      $display("TB_SDF: FAIL: +hex=<file> plusarg missing"); $fatal(1);
    end
    if (!$value$plusargs("expect=%s", expect_str)) expect_str = "";
    // release reset on negedge (avoids the posedge race documented in
    // results/INTERVENTIONS.md)
    repeat (5) @(posedge clk);
    @(negedge clk); #1; rst = 1'b0;
    $display("TB_SDF: reset released, loading %s", hex_path);
    $readmemh(hex_path, dut.rom.mem);
  end

  // ---------------- UART receiver (clock-period parameterized) ----------------
  // 115200 baud => 8680.6 ns/bit. Sample at bit centers.
  localparam real BIT_NS = 1.0e9 / 115200.0;
  string cur = "";
  string lines[$];
  bit rx_busy = 0;
  always @(negedge dut.uart_tx) begin
    if (!rst && !rx_busy) begin
      rx_busy = 1;
      #(BIT_NS/2.0);
      if (dut.uart_tx === 1'b0) begin
        byte b = 8'h00;
        for (int i = 0; i < 8; i++) begin
          #(BIT_NS);
          b[i] = dut.uart_tx;
        end
        #(BIT_NS); // stop bit
        if (b == 8'h0A) begin
          $display("UART: %s", cur);
          lines.push_back(cur);
          cur = "";
        end else if (b != 8'h0D) begin
          cur = $sformatf("%s%c", cur, b);
        end
      end
      rx_busy = 0;
    end
  end

  // ---------------- verdict ----------------
  int timeout_cycles = 0;
  initial begin
    if (!$value$plusargs("timeout_cycles=%d", timeout_cycles))
      timeout_cycles = 2000000;
    fork
      begin
        // wait for the expected string on any UART line
        string l;
        bit found = 0;
        while (!found) begin
          wait (lines.size() > 0);
          l = lines.pop_front();
          if (expect_str != "" && l == expect_str) found = 1;
        end
        $display("TB_SDF: SIM PASS (saw '%s' at cycle %0d)", expect_str, cycle);
        $finish;
      end
      begin
        wait (cycle >= timeout_cycles);
        $display("TB_SDF: FAIL: timeout (%0d cycles) waiting for '%s'",
                 timeout_cycles, expect_str);
        $display("TB_SDF: lines seen: %0d", lines.size());
        $fatal(1);
      end
    join_any
    disable fork;
  end

endmodule
